<?php
declare(strict_types=1);
require dirname(__DIR__) . '/bootstrap.php';
session_set_cookie_params(['httponly' => true, 'secure' => !empty($_SERVER['HTTPS']), 'samesite' => 'Strict']);
session_start();
$pdo = db(); $message = ''; $error = '';
function e($value): string { return htmlspecialchars((string)$value, ENT_QUOTES, 'UTF-8'); }
function insurance_plan_label(array $booking): string
{
    $plan = (string)($booking['insurance_plan'] ?? (!empty($booking['insurance']) ? 'standard' : 'basic'));
    $labels = ['basic' => '基本補償', 'standard' => '安心保険プラン', 'wide' => '安心保険プラン・ワイド'];
    return $labels[$plan] ?? $labels['basic'];
}
function booking_status_label(string $status): string
{
    $labels = ['pending' => '確認待ち', 'confirmed' => '予約確定', 'change_requested' => '変更確認中', 'cancelled' => 'キャンセル'];
    return $labels[$status] ?? '確認待ち';
}
function mail_recipient_label(string $type): string
{
    $labels = ['customer' => 'お客様', 'admin' => '管理会社', 'test' => 'テスト'];
    return $labels[$type] ?? $type;
}
function booking_mailto_url(array $booking, string $vehicleLabel): string
{
    $email = (string)($booking['email'] ?? '');
    if (!filter_var($email, FILTER_VALIDATE_EMAIL)) return '#';
    $status = (string)($booking['status'] ?? 'pending');
    $statusMessages = [
        'pending' => 'ご予約を受け付けました。現在、空車状況とお申し込み内容を確認しております。',
        'confirmed' => 'ご予約が確定しました。当日は運転免許証をご持参のうえ、お気をつけてお越しください。',
        'change_requested' => '変更のご希望を受け付けています。内容を確認のうえ、改めてご連絡いたします。',
        'cancelled' => 'ご予約のキャンセルを受け付けました。',
    ];
    $serviceLabels = ['stay' => '民泊', 'hike' => '登山案内', 'activity' => 'アクティビティ', 'boat' => '漁船遊覧'];
    $selectedServices = json_decode((string)($booking['additional_services'] ?? '[]'), true);
    $services = [];
    if (is_array($selectedServices)) foreach ($selectedServices as $service) $services[] = $serviceLabels[(string)$service] ?? (string)$service;
    $subject = '【KMCUBE】ご予約内容のご案内 ' . (string)$booking['code'];
    $body = (string)$booking['name'] . " 様\n\nKMCUBE Yakushimaです。\n" . ($statusMessages[$status] ?? $statusMessages['pending']) . "\n\n";
    $body .= "―― ご予約内容 ――\n";
    $body .= '予約番号：' . (string)$booking['code'] . "\n";
    $body .= '現在の状態：' . booking_status_label($status) . "\n";
    $body .= '利用日時：' . (string)$booking['start_date'] . ' ' . (string)($booking['start_time'] ?? '09:00') . ' ～ ' . (string)$booking['end_date'] . ' ' . (string)($booking['end_time'] ?? '17:00') . "\n";
    $body .= '車両：' . $vehicleLabel . "\n";
    $body .= '受取・返却場所：' . (string)$booking['pickup_location'] . "\n";
    $body .= '利用人数：' . (int)$booking['people'] . "名\n";
    $body .= '保険・補償：' . insurance_plan_label($booking) . "\n";
    $body .= '追加サービス：' . ($services ? implode('、', $services) : 'なし') . "\n";
    $body .= '概算金額（税込）：¥' . number_format((int)$booking['total']) . "\n\n";
    $body .= "ご不明な点や旅程のご相談がございましたら、このメールへご返信ください。\n\nKMCUBE Yakushima\nbooking@k-mcube.com";
    return 'mailto:' . $email . '?subject=' . rawurlencode($subject) . '&body=' . rawurlencode($body);
}
function logged_in(): bool { return !empty($_SESSION['kmcube_admin']); }
function csrf_ok(): bool { return isset($_SESSION['csrf']) && hash_equals((string)$_SESSION['csrf'], (string)($_POST['csrf'] ?? '')); }
function local_datetime(string $value): ?DateTimeImmutable { $date = DateTimeImmutable::createFromFormat('Y-m-d\TH:i', clean_text($value, 16)); return $date ?: null; }
function store_vehicle_image(array $file, string $vehicleId): ?string
{
    if (($file['error'] ?? UPLOAD_ERR_NO_FILE) === UPLOAD_ERR_NO_FILE) return null;
    if (($file['error'] ?? UPLOAD_ERR_OK) !== UPLOAD_ERR_OK || !is_uploaded_file((string)($file['tmp_name'] ?? ''))) throw new RuntimeException('写真を受信できませんでした。');
    if ((int)($file['size'] ?? 0) > 5 * 1024 * 1024) throw new RuntimeException('写真は5MB以内にしてください。');
    $imageInfo = getimagesize((string)$file['tmp_name']);
    if ($imageInfo !== false && ((int)$imageInfo[0] * (int)$imageInfo[1]) > 24000000) throw new RuntimeException('写真の縦横サイズが大きすぎます。2400万画素以内にしてください。');
    $mime = (string)($imageInfo['mime'] ?? '');
    if (function_exists('finfo_open') && ($finfo = finfo_open(FILEINFO_MIME_TYPE))) { $mime = (string)finfo_file($finfo, (string)$file['tmp_name']); finfo_close($finfo); }
    $extensions = ['image/jpeg'=>'jpg','image/png'=>'png','image/webp'=>'webp'];
    if (!isset($extensions[$mime]) || $imageInfo === false) throw new RuntimeException('JPG、PNG、WebP形式の写真を選択してください。');
    $directory = dirname(__DIR__) . '/uploads/vehicles';
    if (!is_dir($directory) && !mkdir($directory, 0770, true) && !is_dir($directory)) throw new RuntimeException('写真の保存先を作成できませんでした。');
    $filename = $vehicleId . '-' . date('YmdHis') . '-' . bin2hex(random_bytes(4)) . '.' . $extensions[$mime];
    if (!move_uploaded_file((string)$file['tmp_name'], $directory . '/' . $filename)) throw new RuntimeException('写真を保存できませんでした。');
    return '/api/uploads/vehicles/' . $filename;
}
function remove_uploaded_vehicle_image(string $path): void
{
    $uploadPrefix = '/api/uploads/vehicles/';
    if (strncmp($path, $uploadPrefix, strlen($uploadPrefix)) !== 0) return;
    $file = dirname(__DIR__) . '/uploads/vehicles/' . basename($path);
    if (is_file($file)) @unlink($file);
}
if (empty($_SESSION['csrf'])) $_SESSION['csrf'] = bin2hex(random_bytes(20));

if (isset($_GET['logout'])) { $_SESSION = []; session_destroy(); header('Location: ./'); exit; }
if ($_SERVER['REQUEST_METHOD'] === 'POST' && isset($_POST['password'])) {
    if (($config['admin_password'] ?? 'CHANGE_ME_NOW') === 'CHANGE_ME_NOW') $error = 'config.local.php の管理パスワードを変更してから利用してください。';
    elseif (hash_equals((string)$config['admin_password'], (string)$_POST['password'])) { session_regenerate_id(true); $_SESSION['kmcube_admin'] = true; header('Location: ./'); exit; }
    else $error = 'パスワードが正しくありません。';
}

if (logged_in() && isset($_GET['export'])) {
    header('Content-Type: text/csv; charset=UTF-8'); header('Content-Disposition: attachment; filename="kmcube-bookings-' . date('Ymd') . '.csv"'); echo "\xEF\xBB\xBF";
    $output = fopen('php://output', 'w'); fputcsv($output, ['予約番号','状態','担当者','出発日時','返却日時','料金体系','車両','氏名','メール','電話','受取場所','保険・補償プラン','金額','追加サービス','作成日時']);
    foreach ($pdo->query('SELECT b.*,s.name AS assigned_staff_name FROM bookings b LEFT JOIN staff_members s ON s.id=b.assigned_staff_id ORDER BY b.start_date ASC,b.created_at DESC') as $row) fputcsv($output, [$row['code'],$row['status'],$row['assigned_staff_name']??'',$row['start_date'].' '.($row['start_time']??''),$row['end_date'].' '.($row['end_time']??''),$row['billing_mode']??'daily',$row['car_class'],$row['name'],$row['email'],$row['phone'],$row['pickup_location'],insurance_plan_label($row),$row['total'],$row['additional_services'],$row['created_at']]);
    fclose($output); exit;
}

if (logged_in() && $_SERVER['REQUEST_METHOD'] === 'POST' && isset($_POST['mail_action'])) {
    if (!csrf_ok()) $error = '操作を確認できませんでした。画面を再読み込みしてください。';
    elseif ($_POST['mail_action'] === 'test') {
        $testEmail = clean_text($_POST['test_email'] ?? '', 180);
        if (!filter_var($testEmail, FILTER_VALIDATE_EMAIL)) $error = 'テスト送信先のメールアドレスをご確認ください。';
        elseif (send_test_mail($testEmail, $config)) $message = 'テストメールをメールサーバーへ渡しました。受信箱と迷惑メールをご確認ください。';
        else $error = 'テストメールを送信できませんでした。下の送信履歴でエラー内容をご確認ください。';
    } elseif ($_POST['mail_action'] === 'delete_logs') {
        $selected = $_POST['mail_log_ids'] ?? [];
        $ids = [];
        if (is_array($selected)) foreach ($selected as $id) if ((int)$id > 0) $ids[] = (int)$id;
        $ids = array_slice(array_values(array_unique($ids)), 0, 100);
        if (!$ids) $error = '削除する送信履歴を選択してください。';
        else {
            $placeholders = implode(',', array_fill(0, count($ids), '?'));
            $stmt = $pdo->prepare('DELETE FROM mail_delivery_log WHERE id IN (' . $placeholders . ')');
            $stmt->execute($ids);
            $message = $stmt->rowCount() . '件のメール送信履歴を削除しました。';
        }
    }
}

if (logged_in() && $_SERVER['REQUEST_METHOD'] === 'POST' && isset($_POST['vehicle_action'])) {
    if (!csrf_ok()) $error = '操作を確認できませんでした。画面を再読み込みしてください。';
    else {
        $action = (string)$_POST['vehicle_action']; $id = clean_text($_POST['vehicle_id'] ?? '', 20);
        if ($action === 'delete') {
            $existing = find_vehicle($pdo, $id, false);
            $stmt = $pdo->prepare('SELECT (SELECT COUNT(*) FROM bookings WHERE car_class=:id)+(SELECT COUNT(*) FROM availability_blocks WHERE car_class=:id)'); $stmt->execute([':id'=>$id]);
            if ((int)$stmt->fetchColumn() > 0) { $stmt=$pdo->prepare('UPDATE vehicles SET active=0,updated_at=:now WHERE id=:id'); $stmt->execute([':now'=>date('Y-m-d H:i:s'),':id'=>$id]); $message='予約履歴または満車設定があるため削除せず、受付停止にしました。履歴は安全に保持されます。'; }
            else { $stmt=$pdo->prepare('DELETE FROM vehicles WHERE id=:id'); $stmt->execute([':id'=>$id]); if ($existing) remove_uploaded_vehicle_image((string)($existing['image_path']??'')); $message='車両と登録写真を削除し、本サイトへ反映しました。'; }
        } elseif (in_array($action, ['add','update'], true)) {
            $label=clean_text($_POST['vehicle_label']??'',50); $model=clean_text($_POST['vehicle_model']??'',80); $daily=max(0,(int)($_POST['vehicle_daily_price']??0)); $hourly=max(0,(int)($_POST['vehicle_hourly_price']??0)); $inventory=max(0,min(99,(int)($_POST['vehicle_inventory']??0))); $sort=max(0,min(9999,(int)($_POST['vehicle_display_order']??0))); $active=!empty($_POST['vehicle_active'])?1:0;
            if (!preg_match('/^[a-z0-9][a-z0-9_-]{1,19}$/',$id)||$label===''||$model===''||$daily<1||$hourly<1) $error='車両ID、名称、モデル、料金をご確認ください。IDは半角英小文字・数字・ハイフン・下線の2～20文字です。';
            else try {
                $existing = find_vehicle($pdo, $id, false);
                $oldImage = (string)($existing['image_path'] ?? '');
                $uploadedImage = store_vehicle_image($_FILES['vehicle_image'] ?? [], $id);
                $image = $uploadedImage ?? (!empty($_POST['vehicle_remove_image']) ? '' : $oldImage);
                $now=date('Y-m-d H:i:s');
                $sql=$action==='add'?'INSERT INTO vehicles(id,label,model,image_path,daily_price,hourly_price,inventory,active,display_order,created_at,updated_at) VALUES(:id,:label,:model,:image,:daily,:hourly,:inventory,:active,:sort,:now,:now)':'UPDATE vehicles SET label=:label,model=:model,image_path=:image,daily_price=:daily,hourly_price=:hourly,inventory=:inventory,active=:active,display_order=:sort,updated_at=:now WHERE id=:id';
                $stmt=$pdo->prepare($sql); $stmt->execute([':id'=>$id,':label'=>$label,':model'=>$model,':image'=>$image,':daily'=>$daily,':hourly'=>$hourly,':inventory'=>$inventory,':active'=>$active,':sort'=>$sort,':now'=>$now]);
                if ($oldImage !== '' && $oldImage !== $image) remove_uploaded_vehicle_image($oldImage);
                $message=$action==='add'?'車両と写真を登録し、本サイトへ反映しました。':'車両情報と写真を更新し、本サイトへ反映しました。';
            } catch (Throwable $exception) {
                if (!empty($uploadedImage)) remove_uploaded_vehicle_image((string)$uploadedImage);
                $error=strpos($exception->getMessage(),'UNIQUE')!==false?'同じ車両IDが登録されています。別のIDにしてください。':($exception instanceof RuntimeException?$exception->getMessage():'車両情報を保存できませんでした。');
            }
        }
    }
}

if (logged_in() && $_SERVER['REQUEST_METHOD'] === 'POST' && isset($_POST['block_action'])) {
    if (!csrf_ok()) $error='操作を確認できませんでした。画面を再読み込みしてください。';
    elseif ($_POST['block_action']==='delete') { $stmt=$pdo->prepare('DELETE FROM availability_blocks WHERE id=:id'); $stmt->execute([':id'=>(int)($_POST['block_id']??0)]); $message='利用不可設定を解除し、空車検索へ反映しました。'; }
    elseif (in_array($_POST['block_action'],['add','update'],true)) {
        $carClass=clean_text($_POST['block_car_class']??'',20); $start=local_datetime((string)($_POST['block_start_at']??'')); $end=local_datetime((string)($_POST['block_end_at']??'')); $vehicle=find_vehicle($pdo,$carClass,false);
        if (!$vehicle||(int)$vehicle['inventory']<1||!$start||!$end||$end<=$start) $error='車両クラスと利用不可期間をご確認ください。';
        else { $quantity=max(1,min((int)$vehicle['inventory'],(int)($_POST['block_quantity']??1))); $params=[':car'=>$carClass,':start'=>$start->format('Y-m-d H:i:s'),':end'=>$end->format('Y-m-d H:i:s'),':quantity'=>$quantity,':reason'=>clean_text($_POST['block_reason']??'',160)];
            if ($_POST['block_action']==='update') { $stmt=$pdo->prepare('UPDATE availability_blocks SET car_class=:car,start_at=:start,end_at=:end,quantity=:quantity,reason=:reason WHERE id=:id'); $params[':id']=(int)($_POST['block_id']??0); }
            else { $stmt=$pdo->prepare('INSERT INTO availability_blocks(car_class,start_at,end_at,quantity,reason,created_at) VALUES(:car,:start,:end,:quantity,:reason,:created)'); $params[':created']=date('Y-m-d H:i:s'); }
            $stmt->execute($params); $message=$_POST['block_action']==='update'?'満車・利用不可設定を更新しました。':'満車・利用不可設定を登録し、本サイトへ反映しました。'; }
    }
}

if (logged_in() && $_SERVER['REQUEST_METHOD'] === 'POST' && isset($_POST['staff_action'])) {
    if (!csrf_ok()) $error = '操作を確認できませんでした。画面を再読み込みしてください。';
    else {
        $staffAction = (string)$_POST['staff_action'];
        $staffId = max(0, (int)($_POST['staff_id'] ?? 0));
        if ($staffAction === 'add') {
            $staffName = clean_text($_POST['staff_name'] ?? '', 60);
            if ($staffName === '') $error = '担当者名を入力してください。';
            else {
                $now = date('Y-m-d H:i:s');
                $stmt = $pdo->prepare('INSERT INTO staff_members(name,active,created_at,updated_at) VALUES(:name,1,:now,:now)');
                $stmt->execute([':name'=>$staffName, ':now'=>$now]);
                $message = '担当者「' . $staffName . '」を登録しました。';
            }
        } elseif ($staffAction === 'update') {
            $staffName = clean_text($_POST['staff_name'] ?? '', 60);
            $staffActive = !empty($_POST['staff_active']) ? 1 : 0;
            if ($staffId < 1 || $staffName === '') $error = '担当者名をご確認ください。';
            else {
                $stmt = $pdo->prepare('UPDATE staff_members SET name=:name,active=:active,updated_at=:now WHERE id=:id');
                $stmt->execute([':name'=>$staffName, ':active'=>$staffActive, ':now'=>date('Y-m-d H:i:s'), ':id'=>$staffId]);
                $message = '担当者情報を更新しました。';
            }
        } elseif ($staffAction === 'delete') {
            $stmt = $pdo->prepare('SELECT COUNT(*) FROM bookings WHERE assigned_staff_id=:id');
            $stmt->execute([':id'=>$staffId]);
            if ((int)$stmt->fetchColumn() > 0) {
                $stmt = $pdo->prepare('UPDATE staff_members SET active=0,updated_at=:now WHERE id=:id');
                $stmt->execute([':now'=>date('Y-m-d H:i:s'), ':id'=>$staffId]);
                $message = '担当履歴があるため削除せず、選択候補から外しました。';
            } else {
                $stmt = $pdo->prepare('DELETE FROM staff_members WHERE id=:id');
                $stmt->execute([':id'=>$staffId]);
                $message = '担当者を削除しました。';
            }
        }
    }
}

if (logged_in() && $_SERVER['REQUEST_METHOD'] === 'POST' && isset($_POST['booking_id'])) {
    if (!csrf_ok()) $error='操作を確認できませんでした。画面を再読み込みしてください。';
    else {
        $status = (string)($_POST['status'] ?? 'pending');
        $staffId = max(0, (int)($_POST['assigned_staff_id'] ?? 0));
        $staffStmt = $pdo->prepare('SELECT id,name FROM staff_members WHERE id=:id AND active=1');
        $staffStmt->execute([':id'=>$staffId]);
        $assignedStaff = $staffStmt->fetch();
        if (!in_array($status, ['pending','confirmed','cancelled','change_requested'], true)) $error = '状態が正しくありません。';
        elseif (!$assignedStaff) $error = '担当者を選択してから予約状態を保存してください。';
        else {
            $bookingId = (int)$_POST['booking_id'];
            $stmt = $pdo->prepare('UPDATE bookings SET status=:status,assigned_staff_id=:staff,updated_at=:now,cancelled_at=CASE WHEN :status="cancelled" THEN :now ELSE cancelled_at END WHERE id=:id');
            $stmt->execute([':status'=>$status, ':staff'=>$staffId, ':now'=>date('Y-m-d H:i:s'), ':id'=>$bookingId]);
            $message = '担当者「' . (string)$assignedStaff['name'] . '」で予約状態を「' . booking_status_label($status) . '」へ更新しました。';
        }
    }
}

$bookings=[]; $blocks=[]; $vehicles=[]; $vehicleLabels=[]; $mailLogs=[]; $staffMembers=[]; $activeStaffCount=0; $fleetStats=[]; $mailSettings=mail_config($config); $filter='upcoming';
$fleetTotals=['registered'=>0,'in_use'=>0,'blocked'=>0,'available'=>0];
$bookingCounts=['all'=>0,'pending'=>0,'confirmed'=>0,'change_requested'=>0,'cancelled'=>0];
if (logged_in()) {
    $vehicles=vehicle_catalog($pdo,false); foreach($vehicles as $vehicle) $vehicleLabels[$vehicle['id']]=$vehicle['label']; $filter=(string)($_GET['view']??($_GET['status']??'upcoming'));
    $staffMembers=$pdo->query('SELECT * FROM staff_members ORDER BY active DESC,name ASC,id ASC')->fetchAll(); foreach($staffMembers as $staffMember) if(!empty($staffMember['active'])) $activeStaffCount++;
    foreach ($pdo->query('SELECT status, COUNT(*) AS total FROM bookings GROUP BY status')->fetchAll() as $countRow) { $statusKey=(string)$countRow['status']; if(isset($bookingCounts[$statusKey])) $bookingCounts[$statusKey]=(int)$countRow['total']; }
    $bookingCounts['all']=array_sum(array_filter($bookingCounts, function($value, $key){ return $key!=='all'; }, ARRAY_FILTER_USE_BOTH));
    $bookingOrder = "CASE WHEN datetime(COALESCE(NULLIF(b.start_at,''),b.start_date||' '||b.start_time||':00'))<datetime('now','localtime') THEN 1 ELSE 0 END ASC,datetime(COALESCE(NULLIF(b.start_at,''),b.start_date||' '||b.start_time||':00')) ASC,b.created_at DESC";
    $bookingSelect = 'SELECT b.*,s.name AS assigned_staff_name FROM bookings b LEFT JOIN staff_members s ON s.id=b.assigned_staff_id';
    if (in_array($filter,['pending','confirmed','cancelled','change_requested'],true)) { $stmt=$pdo->prepare($bookingSelect.' WHERE b.status=:status ORDER BY '.$bookingOrder.' LIMIT 300'); $stmt->execute([':status'=>$filter]); $bookings=$stmt->fetchAll(); } else { $filter='upcoming'; $bookings=$pdo->query($bookingSelect.' ORDER BY '.$bookingOrder.' LIMIT 300')->fetchAll(); }
    $blocks=$pdo->query("SELECT * FROM availability_blocks ORDER BY end_at>=datetime('now','localtime') DESC,start_at ASC LIMIT 200")->fetchAll();
    $mailLogs=$pdo->query('SELECT * FROM mail_delivery_log ORDER BY id DESC LIMIT 30')->fetchAll();
    $inUseStmt=$pdo->prepare("SELECT COUNT(*) FROM bookings WHERE car_class=:car AND status='confirmed' AND datetime(COALESCE(NULLIF(start_at,''),start_date||' '||start_time||':00'))<=datetime('now','localtime') AND datetime(COALESCE(NULLIF(end_at,''),end_date||' '||end_time||':00'))>datetime('now','localtime')");
    $blockedStmt=$pdo->prepare("SELECT COALESCE(SUM(quantity),0) FROM availability_blocks WHERE car_class=:car AND datetime(start_at)<=datetime('now','localtime') AND datetime(end_at)>datetime('now','localtime')");
    foreach($vehicles as $vehicle){ $inUseStmt->execute([':car'=>$vehicle['id']]); $inUse=(int)$inUseStmt->fetchColumn(); $blockedStmt->execute([':car'=>$vehicle['id']]); $blockedNow=(int)$blockedStmt->fetchColumn(); $registered=max(0,(int)$vehicle['inventory']); $available=max(0,$registered-$inUse-$blockedNow); $fleetStats[]=['id'=>$vehicle['id'],'label'=>$vehicle['label'],'registered'=>$registered,'in_use'=>$inUse,'blocked'=>$blockedNow,'available'=>$available,'active'=>(int)$vehicle['active']]; $fleetTotals['registered']+=$registered; $fleetTotals['in_use']+=$inUse; $fleetTotals['blocked']+=$blockedNow; $fleetTotals['available']+=$available; }
