tbody><?php foreach($mailLogs as $log):?><tr><td class="check-column" data-label="選択"><input class="mail-log-check" type="checkbox" name="mail_log_ids[]" value="<?=e($log['id'])?>" aria-label="<?=e($log['created_at'])?>の送信履歴を選択"></td><td data-label="日時"><?=e($log['created_at'])?></td><td data-label="予約番号"><strong><?=e($log['booking_code']?:'—')?></strong></td><td data-label="送信先の種類"><?=e(mail_recipient_label((string)$log['recipient_type']))?></td><td data-label="送信先"><?=e($log['recipient'])?></td><td data-label="方式"><?=e($log['transport']?:'PHPメール')?></td><td data-label="結果"><span class="mail-result <?=$log['accepted']?'success':'failure'?>"><?=$log['accepted']?'受付':'失敗'?></span></td><td data-label="エラー内容"><?=e($log['error_message']?:'—')?></td></tr><?php endforeach;?></tbody></table></div></form><?php else:?><p class="empty">メール送信履歴はありません。</p><?php endif;?></section>
<section class="fleet-dashboard" aria-labelledby="fleet-dashboard-title"><div class="fleet-heading"><div><small>FLEET STATUS</small><h2 id="fleet-dashboard-title">現在の車両状況</h2><p>登録台数と、いま貸出中・利用不可・貸出可能な台数をまとめて確認できます。</p></div><time datetime="<?=date('c')?>"><?=date('Y/m/d H:i')?> 現在</time></div><div class="fleet-totals"><article class="registered"><small>登録車両</small><strong><?=e($fleetTotals['registered'])?><em>台</em></strong><span>全クラス合計</span></article><article class="in-use"><small>現在貸出中</small><strong><?=e($fleetTotals['in_use'])?><em>台</em></strong><span>予約確定・利用時間内</span></article><article class="available"><small>今すぐ貸出可能</small><strong><?=e($fleetTotals['available'])?><em>台</em></strong><span>現在の空き</span></article><article class="blocked"><small>整備・利用不可</small><strong><?=e($fleetTotals['blocked'])?><em>台</em></strong><span>満車期間の設定分</span></article></div><div class="fleet-classes"><?php foreach($fleetStats as $fleet):$usagePercent=$fleet['registered']>0?min(100,(int)round((($fleet['in_use']+$fleet['blocked'])/$fleet['registered'])*100)):0;?><article><div><strong><?=e($fleet['label'])?></strong><span class="state <?=$fleet['active']?'':'off'?>"><?=$fleet['active']?'受付中':'受付停止'?></span></div><div class="fleet-numbers"><span>登録 <b><?=e($fleet['registered'])?></b>台</span><span>貸出中 <b><?=e($fleet['in_use'])?></b>台</span><span>空き <b><?=e($fleet['available'])?></b>台</span></div><div class="fleet-meter" aria-label="<?=e($fleet['label'])?>の稼働状況"><i style="width:<?=e($usagePercent)?>%"></i></div></article><?php endforeach;?></div></section>
