<?php foreach($bookings as $booking):$change=json_decode($booking['change_request']?:'null',true);$status=(string)$booking['status'];$vehicleLabel=(string)($vehicleLabels[$booking['car_class']]??$booking['car_class']);$mailtoUrl=booking_mailto_url($booking,$vehicleLabel);$serviceIds=json_decode($booking['additional_services']?:'[]',true)?:[];$serviceNames=[];$adminServiceLabels=['stay'=>'民泊','hike'=>'登山案内','activity'=>'アクティビティ','boat'=>'漁船遊覧'];foreach($serviceIds as $serviceId)$serviceNames[]=$adminServiceLabels[$serviceId]??$serviceId;?><tr class="booking-row row-<?=e(str_replace('_','-',$status))?>"><td data-label="予約番号"><strong class="booking-code"><?=e($booking['code'])?></strong><small class="created-at">受付 <?=e($booking['created_at'])?></small></td><td data-label="現在の状態"><span class="status status-<?=e($status)?>"><?=e(booking_status_label($status))?></span><?php if(!empty($booking['assigned_staff_name'])):?><small class="assigned-staff">担当：<?=e($booking['assigned_staff_name'])?></small><?php endif;?></td><td data-label="利用日時"><strong><?=e($booking['start_date'])?> <?=e($booking['start_time']??'09:00')?></strong><span class="date-arrow">↓</span><strong><?=e($booking['end_date'])?> <?=e($booking['end_time']??'17:00')?></strong><small class="data-note"><?=($booking['billing_mode']??'daily')==='hourly'?'時間制':'日数制'?></small></td><td data-label="車両・補償"><strong><?=e($vehicleLabel)?></strong><small class="data-note"><?=e(insurance_plan_label($booking))?></small></td><td data-label="お客様"><strong><?=e($booking['name'])?></strong><a href="mailto:<?=e($booking['email'])?>"><?=e($booking['email'])?></a><a href="tel:<?=e(preg_replace('/[^0-9+]/','',(string)$booking['phone']))?>"><?=e($booking['phone'])?></a></td><td data-label="受取場所・人数"><strong><?=e($booking['pickup_location'])?></strong><span><?=e($booking['people'])?>名</span><?php if(!empty($booking['arrival'])):?><small class="data-note">到着便：<?=e($booking['arrival'])?></small><?php endif;?></td><td data-label="概算料金"><strong class="price">¥<?=number_format((int)$booking['total'])?></strong><small class="data-note">現地払い</small></td><td data-label="追加・ご要望"><?php if($serviceNames):?><strong><?=e(implode('、',$serviceNames))?></strong><?php else:?><span class="muted">追加サービスなし</span><?php endif;?><?php if(!empty($booking['notes'])):?><p class="booking-notes"><?=nl2br(e($booking['notes']))?></p><?php endif;?><?php if($change):?><div class="change"><strong>変更希望あり</strong><br><?=e($change['startDate']??'')?> <?=e($change['startTime']??'')?> ～ <?=e($change['endDate']??'')?> <?=e($change['endTime']??'')?> / <?=e($vehicleLabels[$change['carClass']??'']??($change['carClass']??''))?><br><?=e($change['message']??'')?></div><?php endif;?></td><td data-label="管理操作"><div class="booking-action-panel"><form class="status-form" method="post"><input type="hidden" name="csrf" value="<?=e($_SESSION['csrf'])?>"><input type="hidden" name="booking_id" value="<?=e($booking['id'])?>"><label>担当者 <em>必須</em><select name="assigned_staff_id" required><option value="">選択してください</option><?php foreach($staffMembers as $staff):if(!$staff['active'])continue;?><option value="<?=e($staff['id'])?>" <?=(int)($booking['assigned_staff_id']??0)===(int)$staff['id']?'selected':''?>><?=e($staff['name'])?></option><?php endforeach;?></select></label><label>予約状態<select name="status"><option value="pending" <?=$status==='pending'?'selected':''?>>確認待ち</option><option value="confirmed" <?=$status==='confirmed'?'selected':''?>>予約確定</option><option value="change_requested" <?=$status==='change_requested'?'selected':''?>>変更確認中</option><option value="cancelled" <?=$status==='cancelled'?'selected':''?>>キャンセル</option></select></label><button <?=$staffMembers?'':'disabled'?>>担当者と状態を保存</button></form><a class="mailto-button" href="<?=e($mailtoUrl)?>">メール下書きを開く</a><small class="action-help">メーラーが起動します。定型文を確認・編集してから送信してください。</small></div></td></tr><?php endforeach;?><?php if(!$bookings):?><tr><td class="empty" colspan="9">この状態の予約はありません。</td></tr><?php endif;?></tbody></table></div></main><?php endif;?></body></html>
